css:
@page {
  size: 80mm auto;
  margin: 0;
}

/*
  TRUE TYPE FONT SUPPORT

  Upload the .ttf font file to ERPNext as a public file.
  Example path:
  /files/ReceiptTrueFont.ttf

  If you do not have the .ttf yet, Arial will be used as fallback.
*/
@font-face {
  font-family: "ReceiptTrueFont";
  src: url("/files/ReceiptTrueFont.ttf") format("truetype");
  font-weight: normal;
  font-style: normal;
}

html,
body {
  margin: 0;
  padding: 0;
}

.w80 {
  width: 80mm;
  max-width: 80mm;
  font-size: 11px;
  line-height: 1.3;
  font-family: "ReceiptTrueFont", Arial, Helvetica, sans-serif;
  padding: 2mm 3mm;
  color: #000;
  box-sizing: border-box;
  overflow: hidden;
}

.tc { text-align: center; }
.tr { text-align: right; }
.tl { text-align: left; }
.tb { font-weight: 800; color: #000; }

.logo-wrap {
  text-align: center;
  margin-bottom: 4px;
}

.logo-wrap img {
  max-width: 150px;
  max-height: 75px;
  object-fit: contain;
}

.header-title {
  font-size: 14px;
  font-weight: 900;
  color: #000;
  margin-bottom: 2px;
  letter-spacing: 0.2px;
}

.header-company {
  font-size: 15px;
  font-weight: 900;
  color: #000;
  margin-bottom: 4px;
}

.copy-label {
  font-size: 10px;
  font-weight: 800;
  color: #000;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin: 0;
}

td, th {
  padding: 2px 1px;
  vertical-align: top;
}

th {
  font-weight: 800;
  border-bottom: 1px solid #000;
  padding-bottom: 3px;
  font-size: 10px;
  color: #000;
}

.hr {
  border-top: 1px dashed #333;
  margin: 6px 0;
}

.hr-solid {
  border-top: 1px solid #000;
  margin: 6px 0;
}

.small {
  font-size: 10px;
  line-height: 1.4;
  color: #000;
}

.xsmall {
  font-size: 9px;
  line-height: 1.3;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.info-line {
  margin: 2px 0;
  font-size: 11px;
  word-break: break-word;
  overflow-wrap: anywhere;
}

/* ============================= */
/* Receipt customer/payment block */
/* ============================= */

.receipt-info-box {
  margin: 2px 0;
  font-size: 11px;
  color: #000;
}

.receipt-info-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 6px;
  margin: 2px 0;
  line-height: 1.3;
}

.receipt-label {
  width: 24mm;
  min-width: 24mm;
  font-weight: 800;
  color: #000;
  white-space: nowrap;
}

.receipt-value {
  flex: 1;
  text-align: right;
  word-break: break-word;
  overflow-wrap: anywhere;
  color: #000;
}

.muted-row {
  font-size: 10px;
  opacity: 1;
  color: #000;
}

/* ============================= */
/* Receipt-friendly item layout  */
/* ITEM | TAX | AMOUNT layout    */
/* ============================= */

.items-receipt {
  width: 100%;
  margin: 2px 0;
}

.item-grid-row {
  display: grid;
  grid-template-columns: minmax(0, 48%) 7mm minmax(0, 1fr);
  column-gap: 1.5mm;
  width: 100%;
  align-items: start;
}

.items-header {
  border-bottom: 1px solid #000;
  padding-bottom: 3px;
  font-size: 10px;
  font-weight: 900;
  color: #000;
}

.item-line {
  padding: 4px 0;
  border-bottom: 1px dashed #999;
}

.item-col-name {
  min-width: 0;
  text-align: left;
}

.item-col-tax {
  min-width: 0;
  text-align: center;
}

.item-col-amount {
  min-width: 0;
  text-align: right;
}

.item-name {
  display: block;
  width: 100%;
  max-width: 100%;
  font-size: 10px;
  font-weight: 800;
  color: #000;
  line-height: 1.25;
  word-break: normal;
  overflow-wrap: anywhere;
  white-space: normal;
  hyphens: none;
}

.item-tax {
  font-size: 10px;
  font-weight: 800;
  color: #000;
  line-height: 1.25;
  white-space: nowrap;
}

.item-amount {
  font-size: 9px;
  font-weight: 800;
  color: #000;
  line-height: 1.25;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* Keep old class names harmless in case old HTML still references them */
.vat-class,
.vat-class-inline {
  font-size: 9px;
  font-weight: 800;
  line-height: 1.25;
  white-space: nowrap;
}

.item-title-row,
.item-main-row {
  display: grid;
  grid-template-columns: minmax(0, 48%) 7mm minmax(0, 1fr);
  column-gap: 1.5mm;
  width: 100%;
  align-items: start;
}

.col-item {
  min-width: 0;
  text-align: left;
}

.col-tax {
  min-width: 0;
  text-align: center;
}

.col-amount {
  min-width: 0;
  text-align: right;
}

.item-meta {
  display: flex;
  justify-content: space-between;
  gap: 4px;
  margin-top: 2px;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
}

.item-meta span {
  white-space: nowrap;
}

.item-total {
  font-weight: 800;
}

.amount-text {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* ============================= */
/* Summary table                 */
/* Tighter spacing for receipt   */
/* ============================= */

.summary-table {
  width: 100%;
  margin: 0 !important;
  padding: 0 !important;
  border-collapse: collapse !important;
  border-spacing: 0 !important;
  table-layout: fixed;
}

.summary-table td:first-child {
  width: 55%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.summary-table td:last-child {
  width: 45%;
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.summary-table td {
  padding: 0 !important;
  margin: 0 !important;
  line-height: 1 !important;
  border: none !important;
}

.summary-row td {
  padding: 0 !important;
  margin: 0 !important;
  font-size: 11px;
  line-height: 1 !important;
  color: #000;
}

.tax-deducted-row td {
  font-weight: 800;
}

.total-row td {
  font-weight: 900;
  font-size: 13px;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 1 !important;
  color: #000;
}

/* ============================= */
/* VAT table                     */
/* ============================= */

.vat-header {
  font-weight: 900;
  margin: 4px 0;
  text-align: center;
  font-size: 11px;
  color: #000;
}

.vat-table {
  table-layout: fixed;
}

.vat-table th,
.vat-table td {
  font-size: 9px;
  word-break: break-word;
  overflow-wrap: anywhere;
  color: #000;
}

.vat-table th:nth-child(1),
.vat-table td:nth-child(1) {
  width: 24%;
}

.vat-table th:nth-child(2),
.vat-table td:nth-child(2) {
  width: 25%;
}

.vat-table th:nth-child(3),
.vat-table td:nth-child(3) {
  width: 24%;
}

.vat-table th:nth-child(4),
.vat-table td:nth-child(4) {
  width: 27%;
}

/* ============================= */
/* Footer and fiscal section     */
/* ============================= */

.footer-text {
  margin: 3px 0;
  font-size: 11px;
  color: #000;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.fiscal-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin: 6px 0;
}

.fiscal-left {
  width: 48mm;
  font-size: 9px;
  line-height: 1.35;
  color: #000;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.fiscal-left .fiscal-info {
  text-align: left;
  margin: 1px 0 3px 0;
  font-size: 9px;
}

.fiscal-info {
  font-size: 10px;
  margin: 2px 0;
  color: #000;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.qr-small {
  width: 22mm;
  min-width: 22mm;
  text-align: center;
}

.qr-small img {
  width: 22mm !important;
  height: 22mm !important;
}

.qr-caption {
  font-size: 8px;
  line-height: 1.1;
  margin-top: 2px;
  color: #000;
}

.thank-you {
  margin-top: 6px;
  font-size: 11px;
  font-weight: 800;
  color: #000;
}

.page-break {
  page-break-after: always;
}

@media print {
  html,
  body {
    width: 80mm;
    margin: 0;
    padding: 0;
  }

  .w80 {
    width: 80mm;
    max-width: 80mm;
    padding: 2mm 3mm;
  }

  .no-print {
    display: none !important;
  }

  .qr-small img {
    width: 22mm !important;
    height: 22mm !important;
  }
}

html:
{% for copy_label in ["ORIGINAL", "DUPLICATE (Copy)"] %}

<div class="w80 {% if not loop.last %}page-break{% endif %}">

  {# ============================= #}
  {# Company Info                  #}
  {# ============================= #}
  {% set company = frappe.get_doc("Company", doc.company) %}
  {% set comp_phone = company.phone_no or "" %}
  {% set comp_pin = company.tax_id or "" %}
  {% set company_logo = company.company_logo or "" %}

  {% set addr_name = doc.company_address or doc.company_primary_address or "" %}
  {% set addr = addr_name and frappe.db.get_value(
      "Address",
      addr_name,
      ["address_line1", "address_line2", "city", "state", "pincode", "country"],
      as_dict=True
  ) or None %}

  {# ============================= #}
  {# Receipt Customer Details      #}
  {# ============================= #}
  {% set receipt_customer =
      doc.custom_receipt_customer_name
      or doc.get("receipt_customer_name")
      or doc.get("buyer_name")
      or doc.get("custom_buyer_name")
      or "Walk-in Customer"
  %}

  {% set receipt_phone =
      doc.custom_receipt_phone_number
      or doc.get("receipt_phone_number")
      or doc.get("buyer_phone_number")
      or doc.get("custom_buyer_phone_number")
      or ""
  %}

  {% set account_customer = doc.customer_name or doc.customer or "" %}

  {# ============================= #}
  {# Receipt Totals                #}
  {# ============================= #}
  {% set item_count = (doc.items or [])|length %}
  {% set subtotal = doc.net_total or ((doc.grand_total or 0) - (doc.total_taxes_and_charges or 0)) %}
  {% set final_total = doc.rounded_total or doc.grand_total or 0 %}
  {% set paid_amount = doc.paid_amount or final_total %}
  {% set change_amount = paid_amount - final_total %}

  {# ============================= #}
  {# Weight Accumulators           #}
  {# ============================= #}
  {% set invoice_total_weight_values = [] %}
  {% set invoice_weight_uom_values = [] %}

  {# ============================= #}
  {# Clean Receipt Time            #}
  {# Removes microseconds          #}
  {# ============================= #}
  {% set clean_posting_time = "" %}
  {% if doc.posting_time %}
    {% set clean_posting_time = (doc.posting_time|string).split(".")[0] %}
  {% endif %}

  {# ============================= #}
  {# Deducted Tax Calculation      #}
  {# Negative tax rows are treated #}
  {# as deducted/withholding tax   #}
  {# ============================= #}
  {% set deducted_tax_rows = [] %}
  {% for t in (doc.taxes or []) %}
    {% set tax_amount = frappe.utils.flt(t.tax_amount_after_discount_amount or t.tax_amount or 0) %}
    {% if tax_amount < 0 %}
      {% set _ = deducted_tax_rows.append(frappe.utils.abs(tax_amount)) %}
    {% endif %}
  {% endfor %}
  {% set total_deducted_tax = deducted_tax_rows | sum %}

  <!-- Header -->
  {% if company_logo %}
    <div class="logo-wrap">
      <img src="{{ company_logo }}" alt="{{ doc.company }} Logo">
    </div>
  {% endif %}

  <div class="tc header-title">
    Cash Sales
    {% if copy_label != "ORIGINAL" %}
      <br><span class="copy-label">{{ copy_label }}</span>
    {% endif %}
  </div>

  <div class="tc header-company">{{ doc.company }}</div>

  {% if addr %}
    {% if addr.address_line1 %}
      <div class="tc small">{{ addr.address_line1 }}</div>
    {% endif %}

    {% if addr.address_line2 %}
      <div class="tc small">{{ addr.address_line2 }}</div>
    {% endif %}

    {% set city_state = ((addr.city or "") ~ (addr.state and (", " ~ addr.state) or "")) %}
    {% if city_state %}
      <div class="tc small">{{ city_state }}</div>
    {% endif %}

    {% if addr.pincode %}
      <div class="tc small">{{ addr.pincode }}</div>
    {% endif %}

    {% if addr.country %}
      <div class="tc small">{{ addr.country }}</div>
    {% endif %}
  {% endif %}

  {% if comp_phone %}
    <div class="tc small">Tel: {{ comp_phone }}</div>
  {% endif %}

  {% if comp_pin %}
    <div class="tc small">PIN No: {{ comp_pin }}</div>
  {% endif %}

  <div class="hr"></div>

  <!-- Customer & Receipt Info -->
  <div class="receipt-info-box">
    <div class="receipt-info-row">
      <span class="receipt-label">Customer:</span>
      <span class="receipt-value tb">{{ receipt_customer }}</span>
    </div>

    {% if receipt_phone %}
      <div class="receipt-info-row">
        <span class="receipt-label">Phone:</span>
        <span class="receipt-value">{{ receipt_phone }}</span>
      </div>
    {% endif %}

    {% if account_customer and account_customer != receipt_customer %}
      <div class="receipt-info-row muted-row">
        <span class="receipt-label">Account:</span>
        <span class="receipt-value">{{ account_customer }}</span>
      </div>
    {% endif %}

    {% if doc.tax_id %}
      <div class="receipt-info-row">
        <span class="receipt-label">PIN:</span>
        <span class="receipt-value">{{ doc.tax_id }}</span>
      </div>
    {% endif %}

    <div class="receipt-info-row">
      <span class="receipt-label">Receipt No:</span>
      <span class="receipt-value tb">{{ doc.name }}</span>
    </div>

    <div class="receipt-info-row">
      <span class="receipt-label">Date:</span>
      <span class="receipt-value tb">
        {{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}{% if clean_posting_time %} {{ clean_posting_time }}{% endif %}
      </span>
    </div>

    {% if doc.po_no %}
      <div class="receipt-info-row">
        <span class="receipt-label">Ref:</span>
        <span class="receipt-value">{{ doc.po_no }}</span>
      </div>
    {% endif %}
  </div>

  <div class="hr"></div>

  <!-- Items List -->
  <div class="items-receipt">

    <div class="items-header item-grid-row">
      <span class="item-col-name">ITEM</span>
      <span class="item-col-tax">TAX</span>
      <span class="item-col-amount">AMOUNT</span>
    </div>

    {% for i in (doc.items or []) %}
      {% set item_name = i.item_name or "" %}
      {% set item_code = i.item_code or "" %}
      {% set description = frappe.utils.strip_html(i.description or "") %}
      {% set print_item_name = item_name or item_code or description or "Item" %}

      {# Use the longest available value so names like "Golden Mama Cooking Oil 20 Ltr" are not lost #}
      {% if item_code and (item_code|length > print_item_name|length) %}
        {% set print_item_name = item_code %}
      {% endif %}

      {% if description and (description|length > print_item_name|length) %}
        {% set print_item_name = description %}
      {% endif %}

      {# ============================= #}
      {# Per-Item Weight Calculation   #}
      {# ============================= #}
      {% set item_weight_per_unit = i.get("weight_per_unit") or frappe.db.get_value("Item", i.item_code, "weight_per_unit") or 0 %}
      {% set item_weight_uom = i.get("weight_uom") or frappe.db.get_value("Item", i.item_code, "weight_uom") or "Kg" %}
      {% set item_total_weight = i.get("total_weight") or (frappe.utils.flt(item_weight_per_unit) * frappe.utils.flt(i.qty)) %}

      {% if item_total_weight %}
        {% set _ = invoice_total_weight_values.append(item_total_weight) %}
        {% set _ = invoice_weight_uom_values.append(item_weight_uom) %}
      {% endif %}

      <div class="item-line">

        <div class="item-grid-row">
          <span class="item-col-name item-name">
            {{ print_item_name }}
          </span>

          <span class="item-col-tax item-tax">
            {{ i.custom_vat_class or "-" }}
          </span>

          <span class="item-col-amount item-amount">
            {{ frappe.utils.fmt_money(i.amount, currency=doc.currency) }}
          </span>
        </div>

        <div class="item-meta">
          <span>QTY: {{ frappe.utils.flt(i.qty, 3) }}</span>
          <span>
            RATE:
            <span class="amount-text">
              {{ frappe.utils.fmt_money(i.rate, currency=doc.currency) }}
            </span>
          </span>
          {% if item_total_weight %}
          <span>WT: {{ frappe.utils.flt(item_total_weight, 3) }} {{ item_weight_uom }}</span>
          {% endif %}
        </div>

      </div>
    {% endfor %}

  </div>

  <div class="hr"></div>

  <!-- Summary Table -->
  <table class="summary-table" style="width:100%;border-collapse:collapse;border-spacing:0;margin:0;padding:0;table-layout:fixed;">
    <tr class="summary-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;">{{ item_count }} Item(s) Subtotal</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;">{{ frappe.utils.fmt_money(subtotal, currency=doc.currency) }}</td>
    </tr>

    {% if doc.discount_amount %}
    <tr class="summary-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;">Discount</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;">{{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td>
    </tr>
    {% endif %}

    {% if doc.total_taxes_and_charges %}
    <tr class="summary-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;">Tax</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=doc.currency) }}</td>
    </tr>
    {% endif %}

    {% if total_deducted_tax %}
    <tr class="summary-row tax-deducted-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;font-weight:800;">Tax Deducted</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-weight:800;font-variant-numeric:tabular-nums;">-{{ frappe.utils.fmt_money(total_deducted_tax, currency=doc.currency) }}</td>
    </tr>
    {% endif %}

    {# ============================= #}
    {# Invoice Total Weight Row      #}
    {# ============================= #}
    {% set invoice_total_weight = invoice_total_weight_values | sum %}
    {% set invoice_weight_uom = invoice_weight_uom_values[0] if invoice_weight_uom_values else "Kg" %}

    {% if invoice_total_weight %}
    <tr class="summary-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;">Total Weight</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;">{{ frappe.utils.flt(invoice_total_weight, 3) }} {{ invoice_weight_uom }}</td>
    </tr>
    {% endif %}

    <tr class="total-row" style="line-height:1;">
      <td class="tl tb" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;font-weight:900;font-size:13px;">TOTAL</td>
      <td class="tr tb" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-weight:900;font-size:13px;font-variant-numeric:tabular-nums;">{{ frappe.utils.fmt_money(final_total, currency=doc.currency) }}</td>
    </tr>

    <tr class="summary-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;">Tendered</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;">{{ frappe.utils.fmt_money(paid_amount, currency=doc.currency) }}</td>
    </tr>

    <tr class="summary-row" style="line-height:1;">
      <td class="tl" style="padding:0;margin:0;line-height:1;border:none;width:55%;white-space:nowrap;">Change</td>
      <td class="tr" style="padding:0;margin:0;line-height:1;border:none;width:45%;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;">{{ frappe.utils.fmt_money(change_amount if change_amount > 0 else 0, currency=doc.currency) }}</td>
    </tr>
  </table>

  <div class="hr"></div>

  <!-- VAT Analysis -->
  <div class="vat-header">** VAT BREAKDOWN **</div>

  <table class="vat-table">
    <thead>
      <tr>
        <th class="tl">TAX</th>
        <th class="tr">AMOUNT</th>
        <th class="tr">VAT</th>
        <th class="tr">TOTAL</th>
      </tr>
    </thead>

    <tbody>
      {% set has_tax_rows = [] %}
      {% set manual_vat_items_total = [] %}
      {% set manual_zero_items_total = [] %}
      {% set manual_exempt_items_total = [] %}

      {% for i in (doc.items or []) %}
        {% set vat_class = (i.custom_vat_class or "") | upper %}
        {% set item_amount = frappe.utils.flt(i.amount or 0) %}

        {% if vat_class == "A" %}
          {% set _ = manual_vat_items_total.append(item_amount) %}
        {% elif vat_class == "B" %}
          {% set _ = manual_zero_items_total.append(item_amount) %}
        {% elif vat_class == "E" %}
          {% set _ = manual_exempt_items_total.append(item_amount) %}
        {% endif %}
      {% endfor %}

      {% set manual_vatable_total_inclusive = manual_vat_items_total | sum %}
      {% set manual_vat_amount = frappe.utils.flt(manual_vatable_total_inclusive * 16 / 116, 2) %}
      {% set manual_taxable_amount = frappe.utils.flt(manual_vatable_total_inclusive - manual_vat_amount, 2) %}
      {% set manual_total_with_vat = frappe.utils.flt(manual_vatable_total_inclusive, 2) %}

      {% set manual_zero_amount = manual_zero_items_total | sum %}
      {% set manual_exempt_amount = manual_exempt_items_total | sum %}

      {% for t in (doc.taxes or []) %}
        {% set tax_amount = frappe.utils.flt(t.tax_amount_after_discount_amount or t.tax_amount or 0) %}
        {% set row_total = frappe.utils.flt(t.total or 0) %}
        {% set taxable_amount = row_total - tax_amount %}

        {% if tax_amount != 0 %}
          {% set _ = has_tax_rows.append(1) %}

          <tr class="{% if tax_amount < 0 %}tax-deducted-row{% endif %}">
            <td class="tl small">
              {% if tax_amount < 0 %}
                DED TAX
              {% else %}
                {{ (t.description or t.account_head or "VAT")[:10] }}
              {% endif %}
            </td>

            <td class="tr">
              {{ frappe.utils.fmt_money(taxable_amount, currency=doc.currency) }}
            </td>

            <td class="tr">
              {{ frappe.utils.fmt_money(tax_amount, currency=doc.currency) }}
            </td>

            <td class="tr">
              {{ frappe.utils.fmt_money(row_total, currency=doc.currency) }}
            </td>
          </tr>
        {% endif %}
      {% endfor %}

      {% if not has_tax_rows and manual_vatable_total_inclusive %}
        <tr>
          <td class="tl small">VAT 16%</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_taxable_amount, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_vat_amount, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_total_with_vat, currency=doc.currency) }}</td>
        </tr>
      {% endif %}

      {% if not has_tax_rows and manual_zero_amount %}
        <tr>
          <td class="tl small">ZERO</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_zero_amount, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_zero_amount, currency=doc.currency) }}</td>
        </tr>
      {% endif %}

      {% if not has_tax_rows and manual_exempt_amount %}
        <tr>
          <td class="tl small">EXEMPT</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_exempt_amount, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(manual_exempt_amount, currency=doc.currency) }}</td>
        </tr>
      {% endif %}

      {% if not has_tax_rows and not manual_vatable_total_inclusive and not manual_zero_amount and not manual_exempt_amount %}
        <tr>
          <td class="tl small">VAT</td>
          <td class="tr">{{ frappe.utils.fmt_money(subtotal, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td>
          <td class="tr">{{ frappe.utils.fmt_money(final_total, currency=doc.currency) }}</td>
        </tr>
      {% endif %}
    </tbody>
  </table>

  {% if doc.get("gross_weight") %}
    <div class="small" style="margin-top: 4px;">
      Gross Weight: {{ doc.gross_weight }}
    </div>
  {% endif %}

  <div class="hr"></div>

  <!-- Payment & Server Info -->
  {% set payment_mode = "Cash" %}
  {% if doc.payments and doc.payments|length > 0 %}
    {% set payment_mode = doc.payments[0].mode_of_payment or "Cash" %}
  {% endif %}

  <div class="footer-text">
    Paid VIA: <span class="tb">{{ payment_mode }}</span>
  </div>

  {% set txn_refs = doc.posa_payment_transaction_references or [] %}
  {% if txn_refs %}
    {% for ref in txn_refs %}
      <div class="footer-text">
        Txn Ref{% if ref.mode_of_payment %} ({{ ref.mode_of_payment }}){% endif %}:
        <span class="tb">{{ ref.transaction_reference }}</span>
        {% if ref.amount %} - {{ frappe.utils.fmt_money(ref.amount, currency=doc.currency) }}{% endif %}
      </div>
    {% endfor %}
  {% elif doc.custom_transaction_reference %}
    <div class="footer-text">Txn Ref: <span class="tb">{{ doc.custom_transaction_reference }}</span></div>
  {% elif doc.paid_reference %}
    <div class="footer-text">Ref: {{ doc.paid_reference }}</div>
  {% endif %}

  {# ============================= #}
  {# Sold By - Current Logged-in User #}
  {# ============================= #}

  {% set current_user = frappe.session.user or "" %}

  {% if current_user and current_user != "Administrator" %}
    {% set sold_by_name = frappe.db.get_value("User", current_user, "full_name") or current_user %}
  {% else %}
    {% set sold_by_name = "Cashier" %}
  {% endif %}

  <div class="footer-text">
    Sold By:
    <span class="tb">{{ sold_by_name }}</span>
  </div>

  {# ============================= #}
  {# TIMS / KRA Fiscal Info        #}
  {# ============================= #}

  {% set cu_invoice_number = doc.custom_cu_invoice_number or doc.get("cu_invoice_number") or "" %}
  {% set cu_timestamp = doc.custom_cu_timestamp or doc.get("cu_timestamp") or "" %}
  {% set clean_cu_timestamp = "" %}

  {% if cu_timestamp %}
    {% set clean_cu_timestamp = (frappe.format(cu_timestamp, {"fieldtype": "Datetime"})|string).split(".")[0] %}
  {% endif %}

  {% set verification_url =
    doc.custom_tims_verification_url
    or doc.get("tims_verification_url")
    or doc.get("verification_url")
    or ""
  %}

  {% set qr_payload =
    doc.custom_cu_qr_payload_raw
    or doc.get("cu_qr_payload_raw")
    or doc.get("qr_payload")
    or verification_url
    or ""
  %}

  {% if cu_invoice_number or clean_cu_timestamp or qr_payload %}
    <div class="hr"></div>

    <div class="fiscal-row">
      <div class="fiscal-left">
        {% if cu_invoice_number %}
          <div class="fiscal-info">
            CU NO:<br>{{ cu_invoice_number }}
          </div>
        {% endif %}

        {% if clean_cu_timestamp %}
          <div class="fiscal-info">
            DATE:<br>{{ clean_cu_timestamp }}
          </div>
        {% endif %}
      </div>

      {% if qr_payload %}
        <div class="qr-small">
          <img
            alt="KRA TIMS QR Code"
            src="https://api.qrserver.com/v1/create-qr-code/?size=90x90&data={{ qr_payload | urlencode }}"
          >
          <div class="qr-caption">Scan to verify</div>
        </div>
      {% endif %}
    </div>
  {% endif %}

  <div class="hr"></div>

  <!-- Footer -->
  <div class="tc thank-you">Thank you & welcome again!</div>

</div>

{% endfor %}

css:
@page {
  size: A4;
  margin: 8mm 8mm;
}

* {
  box-sizing: border-box;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 10.5px;
  color: #222;
  background: #fff;
  line-height: 1.3;
}

.invoice-page {
  width: 100%;
  min-height: 100%;
  page-break-after: always;
}

.invoice-page:last-child {
  page-break-after: auto;
}

.page-break {
  page-break-after: always;
}

/* =========================
   CLEAN COMPANY HEADER
========================= */

.clean-header {
  border-bottom: 2px solid #222;
  padding-bottom: 8px;
  margin-bottom: 10px;
  page-break-inside: avoid;
}

.company-identity {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  text-align: left;
}

.company-logo {
  width: 75px;
  min-width: 75px;
  text-align: center;
}

.company-logo img {
  max-width: 75px;
  max-height: 55px;
  object-fit: contain;
}

.company-info-block {
  max-width: 610px;
}

.company-name {
  font-size: 20px;
  font-weight: 800;
  color: #111;
  line-height: 1.1;
  margin-bottom: 3px;
}

.company-address-line {
  font-size: 9.8px;
  color: #444;
  line-height: 1.3;
  margin-bottom: 2px;
}

.company-contact-line {
  font-size: 9.8px;
  color: #444;
  line-height: 1.3;
}

.company-contact-line span {
  display: inline-block;
  margin-right: 8px;
}

.missing-address {
  color: #777;
  font-style: italic;
}

/* =========================
   TOP SUMMARY
========================= */

.top-summary-row {
  display: grid;
  grid-template-columns: 48% 52%;
  gap: 10px;
  margin-bottom: 10px;
  align-items: stretch;
}

.bill-card,
.invoice-card {
  border: 1px solid #d7d7d7;
  border-radius: 6px;
  padding: 9px 10px;
  background: #fff;
  page-break-inside: avoid;
  min-height: 118px;
}

/* =========================
   BILL TO CARD
========================= */

.card-title,
.section-title {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  color: #111;
  padding-bottom: 4px;
  margin-bottom: 6px;
  border-bottom: 1px solid #e8e8e8;
}

.customer-name {
  font-size: 11px;
  font-weight: 800;
  color: #111;
  margin-bottom: 5px;
}

.customer-address,
.customer-pin {
  font-size: 10px;
  color: #444;
  line-height: 1.35;
}

/* =========================
   INVOICE CARD
========================= */

.invoice-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 7px;
  margin-bottom: 7px;
  border-bottom: 1px solid #e8e8e8;
}

.invoice-title {
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.5px;
  color: #111;
  line-height: 1;
  text-transform: uppercase;
  margin: 0;
}

.copy-label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 68px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 8.8px;
  font-weight: 900;
  text-transform: uppercase;
  line-height: 1;
  white-space: nowrap;
}

.copy-original {
  border: 1px solid #222;
  background: #fff;
  color: #111;
}

.copy-copy {
  border: 1px solid #999;
  background: #f5f5f5;
  color: #444;
}

/* =========================
   INVOICE META TABLE
========================= */

.meta-table,
.invoice-meta-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 0;
}

.meta-table td,
.invoice-meta-table td {
  padding: 4px 0;
  font-size: 10.2px;
  vertical-align: top;
}

.meta-table td:first-child,
.invoice-meta-table td:first-child {
  color: #666;
  width: 42%;
}

.meta-table td:last-child,
.invoice-meta-table td:last-child {
  color: #222;
  font-weight: 800;
  text-align: right;
}

/* =========================
   INVOICE DETAILS STRIP
========================= */

.invoice-details-strip {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid #e8e8e8;
  font-size: 10px;
  color: #555;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  justify-content: flex-end;
}

.invoice-details-strip span {
  white-space: nowrap;
}

/* =========================
   ITEMS TABLE
========================= */

.items-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 10px;
  table-layout: fixed;
}

.items-table thead {
  display: table-header-group;
}

.items-table tr {
  page-break-inside: avoid;
}

.items-table th {
  background: #f3f3f3;
  border: 1px solid #dcdcdc;
  padding: 6px 6px;
  font-size: 9.5px;
  font-weight: 800;
  text-transform: uppercase;
  color: #555;
  text-align: left;
}

.items-table td {
  border: 1px solid #e0e0e0;
  padding: 6px 6px;
  font-size: 10px;
  vertical-align: top;
}

.item-name {
  font-weight: 800;
  color: #222;
}

.item-desc {
  font-size: 9px;
  color: #666;
  margin-top: 2px;
}

/* =========================
   SUMMARY
========================= */

.summary-section {
  display: grid;
  grid-template-columns: 54% 42%;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
  page-break-inside: avoid;
}

.tax-table,
.totals-table {
  width: 100%;
  border-collapse: collapse;
}

.tax-table th,
.tax-table td,
.totals-table td {
  border: 1px solid #e0e0e0;
  padding: 6px 6px;
  font-size: 10px;
}

.tax-table th {
  background: #f3f3f3;
  color: #555;
  font-size: 9px;
  text-transform: uppercase;
}

.totals-table td:first-child {
  color: #555;
}

.totals-table td:last-child {
  text-align: right;
  font-weight: 800;
}

.grand-total-row td {
  background: #f3f3f3;
  font-size: 11px;
  font-weight: 900 !important;
  color: #111 !important;
}

/* =========================
   AMOUNT WORDS
========================= */

.amount-words {
  border: 1px solid #dcdcdc;
  border-radius: 6px;
  padding: 7px 9px;
  margin-bottom: 9px;
  font-size: 10px;
  page-break-inside: avoid;
}

/* =========================
   TIMS SECTION
========================= */

.tims-section {
  border: 1px solid #cfcfcf;
  border-radius: 6px;
  padding: 8px;
  margin-bottom: 11px;
  page-break-inside: avoid;
}

.tims-main {
  display: flex;
  align-items: center;
  gap: 10px;
}

.tims-info {
  flex: 1;
}

.tims-row {
  display: grid;
  grid-template-columns: 95px 1fr;
  gap: 8px;
  margin-bottom: 3px;
  font-size: 9.8px;
}

.tims-row span {
  color: #555;
  font-weight: 700;
}

.tims-row b {
  color: #111;
  font-weight: 800;
  word-break: break-word;
}

.error-row b {
  font-size: 9.5px;
}

.qr-box {
  width: 105px;
  min-width: 105px;
  height: 92px;
  border: 1px dashed #777;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  text-align: center;
}

.qr-box img {
  width: 88px !important;
  height: 88px !important;
  object-fit: contain;
}

.qr-missing {
  font-size: 9px;
  font-weight: 900;
  line-height: 1.25;
}

.fiscal-warning {
  margin-top: 6px;
  border: 1px dashed #888;
  padding: 5px 7px;
  font-size: 9.5px;
  font-weight: 800;
  text-align: center;
  background: #fafafa;
}

/* =========================
   NOTES
========================= */

.notes {
  margin-top: 9px;
  font-size: 9.5px;
  color: #555;
  line-height: 1.35;
  page-break-inside: avoid;
}

/* =========================
   SIGNATURES
========================= */

.signatures-section {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-top: 14px;
  page-break-inside: avoid;
  break-inside: avoid;
}

.signature-box {
  flex: 1;
  font-size: 9.8px;
  color: #222;
}

.signature-label {
  font-size: 9.8px;
  font-weight: 900;
  color: #111;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.signature-name-line,
.signature-sign-line {
  width: 100%;
  border-bottom: 1px solid #333;
  min-height: 17px;
  display: flex;
  align-items: flex-end;
  padding-bottom: 2px;
}

.signature-name-line {
  margin-bottom: 2px;
}

.signature-sign-line {
  margin-top: 9px;
  margin-bottom: 2px;
}

.signature-name {
  font-size: 9.8px;
  font-weight: 800;
  color: #111;
}

.signature-helper {
  font-size: 8.5px;
  color: #666;
  line-height: 1.1;
}

/* =========================
   HELPERS
========================= */

.text-right {
  text-align: right;
}

.text-center,
.center {
  text-align: center;
}

.right {
  text-align: right;
}

.bold {
  font-weight: 800;
}

.small {
  font-size: 9px;
}

/* =========================
   PRINT RULES
========================= */

@media print {
  @page {
    size: A4;
    margin: 8mm 8mm;
  }

  html,
  body {
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
  }

  .print-format {
    padding: 0 !important;
    margin: 0 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .invoice-page {
    page-break-after: always;
    break-after: page;
  }

  .invoice-page:last-child {
    page-break-after: auto;
    break-after: auto;
  }

  .clean-header,
  .top-summary-row,
  .bill-card,
  .invoice-card,
  .items-table,
  .summary-section,
  .amount-words,
  .tims-section,
  .signatures-section {
    page-break-inside: avoid;
    break-inside: avoid;
  }

  .items-table thead {
    display: table-header-group;
  }

  .items-table tr {
    page-break-inside: avoid;
    break-inside: avoid;
  }
}

html:
{% for copy_label in ["ORIGINAL", "Copy", "Copy"] %}

<div class="invoice-page {% if not loop.last %}page-break{% endif %}">

  {# ============================= #}
  {# Company Lookups #}
  {# ============================= #}
  {% set company = frappe.get_doc("Company", doc.company) %}

  {% set comp_phone = company.phone_no or company.custom_phone_no or "" %}
  {% set comp_email = company.email or company.email_id or company.custom_email or "" %}
  {% set comp_pin = company.tax_id or company.custom_pin_number or "" %}
  {% set comp_website = company.website or "" %}
  {% set company_logo = company.company_logo or "" %}

  {# First try address from Sales Invoice / Company direct fields #}
  {% set addr_name = doc.company_address or doc.company_primary_address or company.default_company_address or "" %}

  {# If no direct address is found, fetch Address linked to Company through Dynamic Link #}
  {% if not addr_name %}
    {% set linked_addr = frappe.db.get_value(
        "Dynamic Link",
        {
          "link_doctype": "Company",
          "link_name": doc.company,
          "parenttype": "Address"
        },
        "parent"
    ) %}
    {% set addr_name = linked_addr or "" %}
  {% endif %}

  {% set addr = addr_name and frappe.db.get_value(
      "Address",
      addr_name,
      [
        "address_line1",
        "address_line2",
        "city",
        "state",
        "pincode",
        "country",
        "phone",
        "email_id"
      ],
      as_dict=True
  ) or None %}

  {% set addr_phone = addr.phone if addr and addr.phone else "" %}
  {% set addr_email = addr.email_id if addr and addr.email_id else "" %}

  {% set display_phone = comp_phone or addr_phone %}
  {% set display_email = comp_email or addr_email %}

  {# ============================= #}
  {# TIMS Values #}
  {# ============================= #}
  {% set cu_status = doc.custom_cu_status or "Not Fiscalized" %}
  {% set cu_invoice_number = doc.custom_cu_invoice_number or "" %}
  {% set cu_timestamp = doc.custom_cu_timestamp or "" %}
  {% set verification_url = doc.custom_tims_verification_url or "" %}
  {% set qr_payload = doc.custom_cu_qr_payload_raw or verification_url or "" %}
  {% set final_total = doc.rounded_total or doc.grand_total or 0 %}

  {# ============================= #}
  {# Inclusive VAT Calculations #}
  {# A = VAT 16% inclusive, B = zero-rated, E = exempt #}
  {# ============================= #}
  {% set vat_a_amounts = [] %}
  {% set zero_rated_amounts = [] %}
  {% set exempt_amounts = [] %}

  {% for i in (doc.items or []) %}
    {% set vat_class = (i.custom_vat_class or "") | upper %}
    {% set item_total = frappe.utils.flt(i.amount or 0) %}

    {% if vat_class == "A" %}
      {% set _ = vat_a_amounts.append(item_total) %}
    {% elif vat_class == "B" %}
      {% set _ = zero_rated_amounts.append(item_total) %}
    {% elif vat_class == "E" %}
      {% set _ = exempt_amounts.append(item_total) %}
    {% endif %}
  {% endfor %}

  {% set vat_a_total_inclusive = vat_a_amounts | sum %}
  {% set vat_a_tax_amount = frappe.utils.flt(vat_a_total_inclusive * 16 / 116, 2) %}
  {% set vat_a_taxable_amount = frappe.utils.flt(vat_a_total_inclusive - vat_a_tax_amount, 2) %}
  {% set zero_rated_total = zero_rated_amounts | sum %}
  {% set exempt_total = exempt_amounts | sum %}
  {% set display_net_total = frappe.utils.flt((final_total or 0) - (vat_a_tax_amount or 0), 2) %}

  <!-- ============================= -->
  <!-- Top Header -->
  <!-- ============================= -->
  <div class="clean-header">
    <div class="company-identity">
      {% if company_logo %}
      <div class="company-logo">
        <img src="{{ frappe.utils.get_url(company_logo) }}" alt="{{ doc.company }} Logo">
      </div>
      {% endif %}

      <div class="company-info-block">
        <div class="company-name">{{ doc.company }}</div>

        <div class="company-address-line">
          {% if addr %}
            {% if addr.address_line1 %}{{ addr.address_line1 }}{% endif %}
            {% if addr.address_line2 %}{% if addr.address_line1 %}, {% endif %}{{ addr.address_line2 }}{% endif %}
            {% if addr.city %}{% if addr.address_line1 or addr.address_line2 %}, {% endif %}{{ addr.city }}{% endif %}
            {% if addr.state %}, {{ addr.state }}{% endif %}
            {% if addr.pincode %}, {{ addr.pincode }}{% endif %}
            {% if addr.country %}, {{ addr.country }}{% endif %}
          {% else %}
            <span class="missing-address">Company address not set</span>
          {% endif %}
        </div>

        <div class="company-contact-line">
          {% if comp_pin %}<span>KRA PIN: {{ comp_pin }}</span>{% endif %}
          {% if display_phone %}<span>Tel: {{ display_phone }}</span>{% endif %}
          {% if display_email %}<span>Email: {{ display_email }}</span>{% endif %}
          {% if comp_website %}<span>Website: {{ comp_website }}</span>{% endif %}
        </div>
      </div>
    </div>
  </div>

  <!-- ============================= -->
  <!-- Buyer + Invoice Header Row -->
  <!-- ============================= -->
  <div class="top-summary-row">

    <div class="bill-card">
      <div class="card-title">Bill To</div>

      <div class="customer-name">{{ doc.customer_name or doc.customer }}</div>

      {% if doc.customer_address %}
        {% set cust_addr = frappe.db.get_value(
            "Address",
            doc.customer_address,
            ["address_line1", "address_line2", "city", "state", "pincode", "country"],
            as_dict=True
        ) %}

        {% if cust_addr %}
          <div class="customer-address">
            {% if cust_addr.address_line1 %}{{ cust_addr.address_line1 }}<br>{% endif %}
            {% if cust_addr.address_line2 %}{{ cust_addr.address_line2 }}<br>{% endif %}
            {% set c_city_state = ((cust_addr.city or "") ~ (cust_addr.state and (", " ~ cust_addr.state) or "")) %}
            {% if c_city_state %}{{ c_city_state }}<br>{% endif %}
            {% if cust_addr.pincode %}{{ cust_addr.pincode }}<br>{% endif %}
            {% if cust_addr.country %}{{ cust_addr.country }}<br>{% endif %}
          </div>
        {% endif %}
      {% endif %}

      {% if doc.tax_id %}
      <div class="customer-pin">Customer PIN: {{ doc.tax_id }}</div>
      {% endif %}
    </div>

    <div class="invoice-card">
      <div class="invoice-card-header">
        <div class="invoice-title">
          {% if doc.is_return %}
            CREDIT NOTE
          {% else %}
            TAX INVOICE
          {% endif %}
        </div>

        <div class="copy-label {% if copy_label == 'ORIGINAL' %}copy-original{% else %}copy-copy{% endif %}">
          {{ copy_label }}
        </div>
      </div>

      <table class="meta-table invoice-meta-table">
        <tr>
          <td>Invoice No</td>
          <td>{{ doc.name }}</td>
        </tr>

        <tr>
          <td>Posting Date</td>
          <td>{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</td>
        </tr>

        {% if doc.due_date %}
        <tr>
          <td>Due Date</td>
          <td>{{ frappe.format(doc.due_date, {"fieldtype": "Date"}) }}</td>
        </tr>
        {% endif %}

        {% if doc.currency %}
        <tr>
          <td>Currency</td>
          <td>{{ doc.currency }}</td>
        </tr>
        {% endif %}
      </table>

      <div class="invoice-details-strip">
        {% if doc.is_pos %}
          <span>POS Invoice: <b>Yes</b></span>
        {% endif %}

        {% if doc.po_no %}
          <span>Customer PO: <b>{{ doc.po_no }}</b></span>
        {% endif %}

        {% if doc.set_warehouse %}
          <span>Warehouse: <b>{{ doc.set_warehouse }}</b></span>
        {% endif %}

        {% if doc.sales_partner %}
          <span>Sales Partner: <b>{{ doc.sales_partner }}</b></span>
        {% endif %}
      </div>
    </div>

  </div>

  <!-- ============================= -->
  <!-- Items -->
  <!-- ============================= -->
  <table class="items-table">
    <thead>
      <tr>
        <th style="width: 4%;" class="center">#</th>
        <th style="width: 38%;">Item Description</th>
        <th style="width: 9%;" class="center">Qty</th>
        <th style="width: 9%;" class="center">UOM</th>
        <th style="width: 13%;" class="right">Rate</th>
        <th style="width: 9%;" class="center">VAT</th>
        <th style="width: 18%;" class="right">Amount</th>
      </tr>
    </thead>

    <tbody>
      {% for i in doc.items %}
      <tr>
        <td class="center">{{ loop.index }}</td>

        <td>
          <div class="item-name">{{ i.item_name or i.item_code }}</div>

          {% if i.description and i.description != i.item_name %}
            <div class="item-desc">{{ i.description }}</div>
          {% endif %}
        </td>

        <td class="center">{{ frappe.utils.flt(i.qty, 3) }}</td>
        <td class="center">{{ i.uom or "" }}</td>
        <td class="right">{{ frappe.utils.fmt_money(i.rate, currency=doc.currency) }}</td>
        <td class="center">{{ i.custom_vat_class or "-" }}</td>
        <td class="right bold">{{ frappe.utils.fmt_money(i.amount, currency=doc.currency) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- ============================= -->
  <!-- Summary -->
  <!-- ============================= -->
  <div class="summary-section">
    <div class="tax-box">
      <div class="section-title">Tax Summary</div>

      <table class="tax-table">
        <thead>
          <tr>
            <th>Tax Description</th>
            <th class="text-right">Taxable Amount</th>
            <th class="text-right">Tax Amount</th>
          </tr>
        </thead>

        <tbody>
          {% set has_tax_rows = [] %}

          {% for t in (doc.taxes or []) %}
            {% set tax_amount = frappe.utils.flt(t.tax_amount_after_discount_amount or t.tax_amount or 0) %}
            {% set row_total = frappe.utils.flt(t.total or 0) %}
            {% set taxable_amount = frappe.utils.flt(row_total - tax_amount, 2) %}

            {% if tax_amount != 0 %}
              {% set _ = has_tax_rows.append(1) %}
              <tr>
                <td>{{ t.description or t.account_head or "Tax" }}</td>
                <td class="text-right">{{ frappe.utils.fmt_money(taxable_amount, currency=doc.currency) }}</td>
                <td class="text-right">{{ frappe.utils.fmt_money(tax_amount, currency=doc.currency) }}</td>
              </tr>
            {% endif %}
          {% endfor %}

          {% if not has_tax_rows and vat_a_total_inclusive %}
          <tr>
            <td>VAT 16% Inclusive</td>
            <td class="text-right">{{ frappe.utils.fmt_money(vat_a_taxable_amount, currency=doc.currency) }}</td>
            <td class="text-right">{{ frappe.utils.fmt_money(vat_a_tax_amount, currency=doc.currency) }}</td>
          </tr>
          {% endif %}

          {% if not has_tax_rows and zero_rated_total %}
          <tr>
            <td>Zero Rated</td>
            <td class="text-right">{{ frappe.utils.fmt_money(zero_rated_total, currency=doc.currency) }}</td>
            <td class="text-right">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td>
          </tr>
          {% endif %}

          {% if not has_tax_rows and exempt_total %}
          <tr>
            <td>Exempt</td>
            <td class="text-right">{{ frappe.utils.fmt_money(exempt_total, currency=doc.currency) }}</td>
            <td class="text-right">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td>
          </tr>
          {% endif %}

          {% if not has_tax_rows and not vat_a_total_inclusive and not zero_rated_total and not exempt_total %}
          <tr>
            <td>No Tax</td>
            <td class="text-right">{{ frappe.utils.fmt_money(doc.net_total or 0, currency=doc.currency) }}</td>
            <td class="text-right">{{ frappe.utils.fmt_money(0, currency=doc.currency) }}</td>
          </tr>
          {% endif %}
        </tbody>
      </table>
    </div>

    <div class="totals-box">
      <div class="section-title">Invoice Summary</div>

      <table class="totals-table">
        <tr>
          <td>Net Total</td>
          <td>{{ frappe.utils.fmt_money(display_net_total, currency=doc.currency) }}</td>
        </tr>

        {% if vat_a_tax_amount %}
        <tr>
          <td>VAT 16%</td>
          <td>{{ frappe.utils.fmt_money(vat_a_tax_amount, currency=doc.currency) }}</td>
        </tr>
        {% endif %}

        {% if zero_rated_total %}
        <tr>
          <td>Zero Rated</td>
          <td>{{ frappe.utils.fmt_money(zero_rated_total, currency=doc.currency) }}</td>
        </tr>
        {% endif %}

        {% if exempt_total %}
        <tr>
          <td>Exempt</td>
          <td>{{ frappe.utils.fmt_money(exempt_total, currency=doc.currency) }}</td>
        </tr>
        {% endif %}

        {% if doc.discount_amount %}
        <tr>
          <td>Discount</td>
          <td>{{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td>
        </tr>
        {% endif %}

        {% if doc.rounding_adjustment %}
        <tr>
          <td>Rounding Adjustment</td>
          <td>{{ frappe.utils.fmt_money(doc.rounding_adjustment, currency=doc.currency) }}</td>
        </tr>
        {% endif %}

        <tr class="grand-total-row">
          <td>Grand Total</td>
          <td>{{ frappe.utils.fmt_money(final_total, currency=doc.currency) }}</td>
        </tr>

        {% if doc.outstanding_amount %}
        <tr>
          <td>Outstanding</td>
          <td>{{ frappe.utils.fmt_money(doc.outstanding_amount, currency=doc.currency) }}</td>
        </tr>
        {% endif %}
      </table>
    </div>
  </div>

  {% if doc.in_words %}
  <div class="amount-words">
    <span class="bold">Amount in Words:</span> {{ doc.in_words }}
  </div>
  {% endif %}

  <!-- ============================= -->
  <!-- TIMS / KRA Fiscalization -->
  <!-- ============================= -->
  <div class="tims-section">
    <div class="tims-main">
      <div class="tims-info">
        {% if cu_invoice_number %}
        <div class="tims-row">
          <span>CU Invoice No</span>
          <b>{{ cu_invoice_number }}</b>
        </div>
        {% endif %}

        {% if cu_timestamp %}
        <div class="tims-row">
          <span>CU Date/Time</span>
          <b>{{ frappe.format(cu_timestamp, {"fieldtype": "Datetime"}) }}</b>
        </div>
        {% endif %}

        {% if doc.custom_cu_error_message and cu_status != "Fiscalized" %}
        <div class="tims-row error-row">
          <span>Error</span>
          <b>{{ doc.custom_cu_error_message }}</b>
        </div>
        {% endif %}
      </div>

      <div class="qr-box">
        {% if qr_payload %}
          <img
            alt="KRA TIMS QR Code"
            src="https://api.qrserver.com/v1/create-qr-code/?size=95x95&data={{ qr_payload | urlencode }}"
            style="width:95px;height:95px;"
          >
        {% else %}
          <div class="qr-missing">KRA QR<br>NOT AVAILABLE</div>
        {% endif %}
      </div>
    </div>

    {% if cu_status != "Fiscalized" %}
    <div class="fiscal-warning">
      This invoice is not marked as fiscalized. Confirm TIMS fiscalization before issuing the official tax invoice.
    </div>
    {% endif %}
  </div>

  {% if doc.terms %}
  <div class="notes">
    <span class="bold">Terms & Conditions:</span><br>
    {{ doc.terms }}
  </div>
  {% endif %}

  <!-- ============================= -->
  <!-- Signatures -->
  <!-- ============================= -->
  <div class="signatures-section">
    <div class="signature-box">
      <div class="signature-label">Prepared By</div>

      <div class="signature-name-line">
        <span class="signature-name">
          {{ frappe.get_fullname(frappe.session.user) or frappe.session.user }}
        </span>
      </div>
      <div class="signature-helper">Name</div>

      <div class="signature-sign-line"></div>
      <div class="signature-helper">Signature</div>
    </div>

    <div class="signature-box">
      <div class="signature-label">Received By</div>

      <div class="signature-name-line"></div>
      <div class="signature-helper">Name</div>

      <div class="signature-sign-line"></div>
      <div class="signature-helper">Signature</div>
    </div>

    <div class="signature-box">
      <div class="signature-label">Authorized By</div>

      <div class="signature-name-line"></div>
      <div class="signature-helper">Name</div>

      <div class="signature-sign-line"></div>
      <div class="signature-helper">Signature</div>
    </div>
  </div>

</div>

{% endfor %}
